  const IDX = Object.fromEntries(LANGS.map((l, i) => [l.id, i]));
  let lang = 'en';
  const I18N = {
    LANGS,
    get lang() { return lang; },
    get dir() { return (LANGS.find(l => l.id === lang) || LANGS[0]).dir; },
    set(id) { lang = IDX[id] != null ? id : 'en'; document.documentElement.lang = lang; document.documentElement.dir = I18N.dir; },
    t(key, vars) {
      const row = S[key]; let s = row ? (row[IDX[lang]] || row[0]) : key;
      if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
      return s;
    },
    // fills elements marked with data-t (text) and data-tp (placeholder)
    apply(root) {
      (root || document).querySelectorAll('[data-t]').forEach(e => { e.textContent = I18N.t(e.dataset.t); });
      (root || document).querySelectorAll('[data-tp]').forEach(e => { e.placeholder = I18N.t(e.dataset.tp); });
    },
    // best guess from the device language, English otherwise
    detect() { const n = (navigator.language || 'en').slice(0, 2).toLowerCase(); return IDX[n] != null ? n : 'en'; },
  };
  window.I18N = I18N;
  window.t = I18N.t;
